#!/bin/bash
# Z80 / R800 context switch of msx_cpu (Verilator --timing).
#   wsl.exe -- bash rtl/tb/run_cpu_switch.sh            all CPU speeds
#   wsl.exe -- bash rtl/tb/run_cpu_switch.sh +sel=1 +v  single run, verbose
# ALT=<dir> takes tv80.sv, tv80a.sv, tv80_reg.sv and msx_cpu.sv from <dir> and builds the tb
# without the switch ports (OLD_CPU): the core before the switch must fail.
# cpu_switch_prog.svh is generated by cpu_switch_prog.py.
set -e
cd "$(dirname "$0")"
CPU=../peripheral/CPU
DEF=""
[ -n "$ALT" ] && DEF="+define+OLD_CPU"
OUT=$(mktemp -d)
verilator --binary --timing -Wno-fatal -Wno-lint -Wno-style -O2 $DEF \
    --top-module cpu_switch_tb -Mdir "$OUT" -I. \
    ../package.sv ../clock.sv $CPU/tv80_alu.sv $CPU/tv80_mcode.sv "${ALT:-$CPU}/tv80_reg.sv" \
    "${ALT:-$CPU}/tv80.sv" "${ALT:-$CPU}/tv80a.sv" "${ALT:-..}/msx_cpu.sv" cpu_switch_tb.sv \
    > "$OUT/build.log" 2>&1 || { cat "$OUT/build.log"; exit 1; }
grep -E '%Error' "$OUT/build.log" || true

if [ $# -gt 0 ]; then
    "$OUT/Vcpu_switch_tb" "$@" | grep -E "PASS|FAIL|switch|E5|marker"
else
    for s in 0 2 1; do
        "$OUT/Vcpu_switch_tb" +sel=$s | grep -E "PASS|FAIL"
    done
fi
rm -rf "$OUT"
